'use client'

import * as React from 'react'

import { useStrings, type StringsOverrides } from './strings'
import { CrossGlyph } from './glyphs'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Message, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './message.css'

/**
 * Message: one thing somebody said, and where it stands with the screen.
 *
 * Specimen 6a draws five states and specimen 6b draws four speakers. Both are
 * props. The component screens nothing, holds no clock and keeps no history:
 * TalkBox does the screening, the host hands back a state, and this draws it,
 * which is the same seam the cue runtime uses for sound.
 *
 * The five states are one attribute because a message is in exactly one of
 * them. `sending` and `screening` are before the room has it, `published` is
 * the only one anybody else sees, and `held` and `refused` are what a refusal
 * or a hold looks like to the person who wrote it.
 *
 * A refused message stays on screen, struck through, so its author can see
 * which of their messages did not land. It disappears for nobody else because
 * nobody else ever had it, and that is the host's job rather than this
 * component's: a host never sends `refused` or `screening` to another player.
 * Given one, this draws it, because a component that hid a message would be
 * deciding something.
 *
 * The text is rendered as text. A player's words are never markup.
 */

export type MessageAuthor = 'you' | 'player' | 'host' | 'system'

export type MessageModeration = 'sending' | 'screening' | 'published' | 'held' | 'refused'

export interface MessageProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Per-instance vocabulary, merged over the provider. */
  strings?: StringsOverrides

  /** Who is speaking. `player` is somebody else in the room. */
  author?: MessageAuthor
  /**
   * The speaker's display name, as the host spells it. Drawn above the first
   * bubble of a group for `player` and `host`; a host with no name is labelled
   * by the host word alone.
   */
  name?: string
  /**
   * The same speaker as the message before it. The name and the avatar are
   * left out and the bubble sits tight under the last one, the way every
   * messaging app groups a run of messages, so a burst reads as one speaker
   * rather than as a column of repeated faces. The space the avatar held is
   * kept, so the bubbles stay in one line.
   */
  continued?: boolean
  /**
   * The speaker's avatar, as a node. Absent and the initial of `name` stands in,
   * because the drawing gives every named speaker a disc and a blank disc says
   * less than a letter does.
   */
  avatar?: React.ReactNode
  /** Where the message stands with the screen. Host-declared in every value. */
  moderation?: MessageModeration
  /**
   * The time, already formatted by the host. The library holds no clock and no
   * locale. Drawn only once the message is published, which is where the
   * drawing puts it: before that the status line has something to say instead.
   */
  time?: string
  /** Held at the top of a stream rather than scrolling away with the rest. */
  pinned?: boolean
  /** What was said. Text, never markup. */
  children?: React.ReactNode
}

/**
 * Emphasis a player can see without colour and read without sight. The drawing
 * types an exclamation mark inside a warning-coloured ring for a held message;
 * `tip` types the same mark for the same reason. There is no alert mark in the
 * shared glyph set on this branch, which is GSUI-262.
 */
const HELD_MARK = '!'

export function Message(props: MessageProps) {
  const { strings, ...componentProps } = props
  const copy = useStrings(strings)

  const {
    author = 'player',
    name,
    avatar,
    moderation = 'published',
    time,
    pinned = false,
    continued = false,
    className,
    children,
    ...rest
  } = componentProps

  const authorWord =
    author === 'you' ? copy['message.you']
    : author === 'host' ? (name !== undefined ? `${name}, ${copy['message.host']}` : copy['message.host'])
    : author === 'system' ? copy['message.system']
    : name ?? copy['message.player']

  const stateWord =
    moderation === 'sending' ? copy['message.sending']
    : moderation === 'screening' ? copy['message.screening']
    : moderation === 'held' ? copy['message.held']
    : moderation === 'refused' ? copy['message.refused']
    : copy['message.published']

  // The room itself speaking owns no name and no avatar, which is what makes a
  // system line read as unowned. Host and player both keep theirs.
  const named = author === 'player' || author === 'host'
  // A host with no name still gets a letter on its disc: the host word's.
  const initial = [...(name ?? (author === 'host' ? copy['message.host'] : ''))][0]

  return (
    <div
      {...rest}
      className={['gs-message', className].filter(Boolean).join(' ')}
      data-gs-component="message"
      data-gs-author={author}
      data-gs-moderation={moderation}
      data-gs-pinned={pinned ? 'true' : undefined}
      data-gs-continued={continued ? 'true' : undefined}
      // Every state is in the name, because a screen reader user gets no fill,
      // no stroke and no glyph. Published says so too: silence there would make
      // the one state everybody else can see the one state nobody is told.
      role="group"
      aria-label={copy['message.label'](authorWord, stateWord)}
    >
      {named ? (
        <span className="gs-message__avatar" data-gs-scope="message" data-gs-part="avatar" aria-hidden="true">
          {avatar ?? initial}
        </span>
      ) : null}

      <div className="gs-message__column">
        {/* Who is speaking, once per group, level with the avatar: the name, and
            for the host a small word beside it rather than a floating badge. */}
        {named && !continued && (author === 'host' || name !== undefined) ? (
          <span className="gs-message__who" data-gs-scope="message" data-gs-part="label">
            {name !== undefined ? <span className="gs-message__name">{name}</span> : null}
            {author === 'host' ? <span className="gs-message__badge">{copy['message.host']}</span> : null}
          </span>
        ) : null}

        <span className="gs-message__body" data-gs-scope="message" data-gs-part="body">{children}</span>

        {moderation === 'published' ? (
          time !== undefined ? (
            <span className="gs-message__time" data-gs-scope="message" data-gs-part="detail">{time}</span>
          ) : null
        ) : (
          <span className="gs-message__note" data-gs-scope="message" data-gs-part="note">
            {moderation === 'sending' || moderation === 'screening' ? (
              <span
                className="gs-message__busy"
                data-gs-scope="message" data-gs-part="busy"
                // Sending turns; screening waits. Only the turning one moves,
                // so only the turning one is motion.
                data-gs-motion={moderation === 'sending' ? 'rays' : undefined}
                data-gs-animates={moderation === 'sending' ? 'motion' : 'emphasis'}
                aria-hidden="true"
              />
            ) : (
              <span
                className="gs-message__glyph"
                data-gs-scope="message" data-gs-part="glyph"
                data-gs-animates="emphasis"
                aria-hidden="true"
              >
                {moderation === 'refused' ? <CrossGlyph /> : HELD_MARK}
              </span>
            )}
            {stateWord}
          </span>
        )}
      </div>
    </div>
  )
}

/* Message. Every value comes from a token; nothing here is a literal colour.

   Specimen 6a draws the five moderation states and 6b draws the four speakers.
   The drawing's bubble is padded 10 by 14, which is space.gap by space.inset,
   rounded 16 with one 4px tail corner on the side the speaker is on, at the
   top beside the avatar for everybody else and at the foot for the player.
   Bubbles are flat and carry no outline: who spoke is told by side and fill,
   the way every messaging app tells it. Moderation states add an outline back,
   because there it is the signal. 16 is
   radius.control; nothing in the scale carries 4, so the tail is written as a
   length with this note rather than bent onto a token that means something
   else. GSUI-266 is the token request. */

.gs-message {
  display: flex;
  align-items: flex-end;
  gap: var(--gs-space-2);
}

.gs-message__column {
  display: flex;
  flex-direction: column;
  gap: var(--gs-space-1);
  min-width: 0;
  /* The drawing holds a bubble to 250 of a 390 frame, so a long message wraps
     rather than running the width of the room. */
  max-width: 64%;
}

/* -- who is speaking ------------------------------------------------------- */

/* Named speakers line their avatar up with the first bubble of a group, the
   way messaging apps do: the face sits beside the name and the first thing
   they said, not at the foot of a stack. */
.gs-message[data-gs-author='player'],
.gs-message[data-gs-author='host'] {
  align-items: flex-start;
}

/* A run from one speaker: no name, no face, and tight under the last bubble.
   The avatar's space stays so the bubbles hold one line. */
.gs-message[data-gs-continued='true'] {
  margin-block-start: calc(var(--gs-space-1) - var(--gs-space-2));
}

.gs-message[data-gs-continued='true'] .gs-message__avatar {
  visibility: hidden;
}

/* Yours sits on the right, filled in the player's own colour, and the tail is
   on the right with it. No outline: the fill is the whole difference, which is
   why it is a fill and not a thin line of colour round the same blue. */
.gs-message[data-gs-author='you'] {
  justify-content: flex-end;
}

.gs-message[data-gs-author='you'] .gs-message__column {
  align-items: flex-end;
}

.gs-message[data-gs-author='you'] .gs-message__body {
  color: var(--gs-color-on-bright);
  background: var(--gs-color-player);
  border-color: transparent;
  border-radius: var(--gs-radius-control) var(--gs-radius-control) 4px var(--gs-radius-control);
}

/* Everybody else, and the host, on the left with the tail on the left. */
.gs-message[data-gs-author='player'] .gs-message__body,
.gs-message[data-gs-author='host'] .gs-message__body {
  border-radius: 4px var(--gs-radius-control) var(--gs-radius-control) var(--gs-radius-control);
}

/* A run keeps the tail only on its first bubble. */
.gs-message[data-gs-continued='true'][data-gs-author='player'] .gs-message__body,
.gs-message[data-gs-continued='true'][data-gs-author='host'] .gs-message__body {
  border-radius: var(--gs-radius-control);
}

/* The host is read before anybody under it, so it sits on the raised surface.
   Flat: no drop edge, because a bubble is not something to press. */
.gs-message[data-gs-author='host'] .gs-message__body {
  background: var(--gs-color-surface-raised);
  border-color: transparent;
}

/* The room itself, owned by nobody: centred, no avatar, no name, no tail. */
.gs-message[data-gs-author='system'] {
  justify-content: center;
}

.gs-message[data-gs-author='system'] .gs-message__column {
  align-items: center;
  max-width: 100%;
}

.gs-message[data-gs-author='system'] .gs-message__body {
  padding: var(--gs-space-1) var(--gs-space-3);
  background: transparent;
  border: 0;
  border-radius: var(--gs-radius-full);
  font-size: var(--gs-type-caption-font-size);
  color: var(--gs-color-ink-secondary);
}

/* -- the parts ------------------------------------------------------------- */

.gs-message__avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  box-sizing: border-box;
  width: var(--gs-size-icon-control);
  height: var(--gs-size-icon-control);
  overflow: hidden;

  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  line-height: 1;
  text-transform: uppercase;

  color: var(--gs-color-on-bright);
  background: var(--gs-color-opponent);
  /* A disc whatever the theme's corner scale says: Paper's full radius is
     small, and an avatar that turns square stops reading as a face. */
  border-radius: 50%;
}

.gs-message[data-gs-author='host'] .gs-message__avatar {
  background: var(--gs-color-reward);
}

/* Name and the host word on one line, level with the top of the avatar. */
.gs-message__who {
  display: inline-flex;
  align-items: center;
  gap: var(--gs-space-1);
  min-height: var(--gs-size-icon-control);
}

.gs-message__name {
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  color: var(--gs-color-ink);
}

/* The host word: small, quiet, beside the name. The eyebrow face gives it its
   shape; the reward colour says who it is without a plate behind it. */
.gs-message__badge {
  font-family: var(--gs-type-eyebrow-font-family);
  font-size: var(--gs-type-eyebrow-font-size);
  font-weight: var(--gs-type-eyebrow-font-weight);
  letter-spacing: var(--gs-type-eyebrow-letter-spacing);
  text-transform: var(--gs-type-eyebrow-text-transform, none);
  /* The solid form: a theme's reward can be a gradient, which is not a colour
     text can take, and Arcade's host word fell back to plain white. */
  color: var(--gs-color-reward-solid);
}

.gs-message__body {
  align-self: flex-start;
  padding: var(--gs-space-gap) var(--gs-space-inset);

  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-body-font-weight);
  line-height: var(--gs-type-body-line-height);
  overflow-wrap: anywhere;

  color: var(--gs-color-ink);
  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid transparent;
  border-radius: var(--gs-radius-control);
  transition: opacity var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis);
}

.gs-message[data-gs-author='you'] .gs-message__body {
  align-self: flex-end;
}

.gs-message__note,
.gs-message__time {
  display: inline-flex;
  align-items: center;
  gap: var(--gs-space-1);

  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-caption-font-size);
  font-weight: var(--gs-type-body-font-weight);
  color: var(--gs-color-muted);
}

.gs-message__glyph {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  box-sizing: border-box;
  width: var(--gs-size-icon-utility);
  height: var(--gs-size-icon-utility);
  font-family: var(--gs-type-display-font-family);
  font-size: var(--gs-type-caption-font-size);
  line-height: 1;
  border-radius: var(--gs-radius-full);
  transition: color var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis);
}

/* The indicator that something is happening to the message: a ring that turns
   while it is sending, and a square that waits while it is being read. */
.gs-message__busy {
  display: inline-block;
  flex: none;
  box-sizing: border-box;
  width: var(--gs-size-icon-utility);
  height: var(--gs-size-icon-utility);
  border: var(--gs-stroke-selected, var(--gs-stroke-hairline)) solid currentColor;
  border-radius: var(--gs-radius-sm);
}

/* -- where the message stands ---------------------------------------------- */

/* Sending: on screen from the moment of the press, at a little over half
   strength, so nothing waits on a blank. */
.gs-message[data-gs-moderation='sending'] .gs-message__body { opacity: 0.55; }

.gs-message[data-gs-moderation='sending'] .gs-message__busy {
  border-top-color: transparent;
  border-radius: var(--gs-radius-full);
}

/* Screening: a dashed edge, and a sentence saying who can see it, because
   nobody works that out on their own. */
.gs-message[data-gs-moderation='screening'] .gs-message__body {
  opacity: 0.8;
  border-style: dashed;
  border-color: var(--gs-color-edge-high);
}

.gs-message[data-gs-moderation='screening'] .gs-message__note { color: var(--gs-color-ink-secondary); }

/* Held: a person is reading it and it may still post, so the colour stops
   short of a refusal and so does the wording. */
.gs-message[data-gs-moderation='held'] .gs-message__body { border-color: var(--gs-color-warning); }

.gs-message[data-gs-moderation='held'] .gs-message__note { color: var(--gs-color-warning); }

.gs-message[data-gs-moderation='held'] .gs-message__glyph {
  color: var(--gs-color-warning);
  border: var(--gs-stroke-selected, var(--gs-stroke-hairline)) solid var(--gs-color-warning);
}

/* Your own message leaves the player fill once it is held back or refused, so
   the warning edge and the struck words sit on a surface they can be read on. */
.gs-message[data-gs-author='you'][data-gs-moderation='held'] .gs-message__body,
.gs-message[data-gs-author='you'][data-gs-moderation='refused'] .gs-message__body {
  color: var(--gs-color-ink);
  background: var(--gs-color-surface);
}

/* Refused: three changes at once, per BDS-012. Stroke, a cross, and the words
   struck through. Colour alone would tell a colour-blind player nothing. */
.gs-message[data-gs-moderation='refused'] .gs-message__body {
  border-color: var(--gs-color-negative-base);
  color: var(--gs-color-muted);
  text-decoration: line-through;
  text-decoration-color: var(--gs-color-muted);
}

.gs-message[data-gs-moderation='refused'] .gs-message__note { color: var(--gs-color-ink-secondary); }

.gs-message[data-gs-moderation='refused'] .gs-message__glyph {
  color: var(--gs-color-on-accent);
  background: var(--gs-color-negative);
  border: var(--gs-stroke-selected, var(--gs-stroke-hairline)) solid var(--gs-color-negative-base);
}

/* Arcade's surfaces are gradients. Painted from the padding box, the gradient
   repeated under the transparent edge and drew a bright line along the foot of
   every bubble, which read as the drop edge this redesign removes. Last in the
   file and as specific as the speaker rules, because each of those sets the
   background shorthand, which resets the origin. */
.gs-message[data-gs-author] .gs-message__body {
  background-origin: border-box;
}
